启动任务@Componentpublic class QuartzTest &#123;    @PostConstruct    public void startQuartzJob() throws SchedulerException &#123;        // 1.创建quartz任务调度器        Scheduler scheduler = StdSchedulerFactory.getDefaultScheduler();        // 2.创建任务        JobDetail jobDetail = JobBuilder.newJob(MyJob.class).build();        // 3.创建触发器，用来定义任务调度的时机（例如：延时，循环，定时...）        SimpleScheduleBuilder simpleScheduleBuilder = SimpleScheduleBuilder.simpleSchedule()                .withIntervalInSeconds(5) // 间隔时间,每隔5秒执行一次                .withRepeatCount(10); // 重复次数，不算首次，一共重复执行10次，所以一共会执行11次，如果不设置，这里默认情况下为0        SimpleTrigger trigger1 = TriggerBuilder.newTrigger()                .withIdentity(&quot;trigger1&quot;, &quot;group1&quot;)  //触发器的唯一标识 name + group                .startAt(new Date(System.currentTimeMillis() + 5000)) // 定时任务的启动时机                .withSchedule(simpleScheduleBuilder) // 绑定重复调度的策略                .build();        SimpleTrigger trigger2 = TriggerBuilder.newTrigger()                .withIdentity(&quot;trigger2&quot;, &quot;group1&quot;)  //触发器的唯一标识 name + group                .startAt(new Date(System.currentTimeMillis() + 5000)) // 定时任务的启动时机                .withSchedule(simpleScheduleBuilder) // 绑定重复调度的策略                .forJob(jobDetail)                .build();        // 4.将触发器和任务绑定到任务调度器        scheduler.scheduleJob(jobDetail, trigger1);        scheduler.scheduleJob(trigger2);        // 5.开始定时任务        scheduler.start();    &#125;&#125;

