其他定时任务的其他操作实际上，在Quartz中除了能增加任务以外，还可以暂停，重启，删除任务，下面给出实际开发中用到的代码：
暂停定时任务/** * 暂停定时任务 * * @param jobId 任务ID * @return 响应结果 */@PostMapping(&quot;/pauseJob&quot;)public ResultBean pauseJob(@RequestParam String jobId) &#123;    log.info(&quot;暂停任务&quot;);    try &#123;        Scheduler scheduler = schedulerFactoryBean.getScheduler();        JobKey jobKey = new JobKey(&quot;RecentAccessRulesScanTask&quot;, &quot;RecentAccessJob_&quot; + jobId);        // 检查目标Job是否正在运行中        JobDetail jobDetail = scheduler.getJobDetail(jobKey);        if (jobDetail == null) &#123;            return ResultBean.success(false);        &#125;        scheduler.pauseJob(jobKey);    &#125; catch (SchedulerException e) &#123;        e.printStackTrace();        return ResultBean.success(false);    &#125;    return ResultBean.success(true);&#125;

恢复定时任务/** * 恢复定时任务 * * @param jobId 任务ID * @return 响应结果 */@PostMapping(&quot;/resumeJob&quot;)public ResultBean resumeJob(@RequestParam String jobId) &#123;    log.info(&quot;恢复任务&quot;);    try &#123;        Scheduler scheduler = schedulerFactoryBean.getScheduler();        JobKey jobKey = new JobKey(&quot;RecentAccessRulesScanTask&quot;, &quot;RecentAccessJob_&quot; + jobId);        JobDetail jobDetail = scheduler.getJobDetail(jobKey);        if (jobDetail == null) &#123;            return ResultBean.success(false);        &#125;        scheduler.resumeJob(jobKey);    &#125; catch (SchedulerException e) &#123;        e.printStackTrace();        return ResultBean.success(false);    &#125;    return ResultBean.success(true);&#125;

删除定时任务/** * 删除定时任务 * * @param jobId 任务ID * @return 响应结果 */@PostMapping(&quot;/deleteJob&quot;)public ResultBean deleteJob(@RequestParam String jobId) &#123;    log.info(&quot;删除任务&quot;);    try &#123;        Scheduler scheduler = schedulerFactoryBean.getScheduler();        JobKey jobKey = new JobKey(&quot;RecentAccessRulesScanTask&quot;, &quot;RecentAccessJob_&quot; + jobId);        JobDetail jobDetail = scheduler.getJobDetail(jobKey);        if (jobDetail == null) &#123;            return ResultBean.success(false);        &#125;        scheduler.deleteJob(jobKey);    &#125; catch (SchedulerException e) &#123;        e.printStackTrace();        return ResultBean.success(false);    &#125;    return ResultBean.success(true);&#125;

